      display: grid;
      grid-template-columns: 1fr;
      gap: 1.5rem;
      position: relative;
      overflow: hidden;
    }
    .hero-main::after {
      content: "";
      position: absolute;
      inset: auto -6rem -7rem auto;
      width: 18rem;
      height: 18rem;
      background: radial-gradient(circle, rgba(245, 215, 198, 0.95), rgba(245, 215, 198, 0));
