    }

    .grid {
      display: grid;
      gap: 1rem;
    }
    .featured-grid {
      grid-template-columns: repeat(12, 1fr);
    }
    .card {
      border-radius: 24px;
      padding: 1rem;
      display: grid;
      gap: 1rem;
      min-height: 100%;
    }
    .featured-grid .card:nth-child(1) { grid-column: span 5; }
    .featured-grid .card:nth-child(2) { grid-column: span 4; }
    .featured-grid .card:nth-child(3) { grid-column: span 3; }

    .product-visual {
      border-radius: 20px;
      min-height: 180px;
      background: linear-gradient(135deg, rgba(28,26,23,0.08), rgba(173,92,47,0.2));
      display: grid;
      place-items: center;
      position: relative;
      overflow: hidden;
    }
    .product-visual::before {
      content: "";
      width: 9rem;
      height: 9rem;
      border-radius: 38% 62% 48% 52% / 43% 34% 66% 57%;
      background: linear-gradient(145deg, rgba(173,92,47,0.25), rgba(255,255,255,0.65));
      box-shadow: inset 0 0 0 1px rgba(255,255,255,0.45);
    }
    .product-visual.one { background: linear-gradient(135deg, #efe3d8, #f8f1eb); }
    .product-visual.two { background: linear-gradient(135deg, #e0e7dd, #f4f7f2); }
    .product-visual.three { background: linear-gradient(135deg, #f2e0d2, #fff6ef); }

    .product-meta {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      align-items: start;
    }
    .product-meta h3, .deal-card h3, .editorial-card h3 { margin-bottom: 0.35rem; }
    .price {
      font-weight: 800;
      color: var(--text);
      white-space: nowrap;
    }
    .rating {
      color: #8f6d00;
      font-size: 0.92rem;
    }

    .deal-layout {
      grid-template-columns: 1.2fr 0.8fr;
      align-items: stretch;
    }
    .deal-banner, .deal-card, .editorial-card, .promo-card {
      border-radius: 24px;
      padding: 1.25rem;
    }
    .deal-banner {
      background: linear-gradient(145deg, #1e2b24, #304236 50%, #213128);
      color: #fff;
      display: grid;
      gap: 1rem;
      min-height: 100%;
    }
    .deal-banner .eyebrow, .deal-banner .muted { color: rgba(255,255,255,0.72); }
    .deal-banner h2 {
      font-size: clamp(2rem, 4vw, 3.5rem);
      letter-spacing: -0.04em;
      margin-bottom: 0;
    }
    .deal-banner .timer {
      display: inline-flex;
      gap: 0.75rem;
      flex-wrap: wrap;
    }
    .timer span {
      background: rgba(255,255,255,0.12);
      border-radius: 18px;
      padding: 0.8rem 0.9rem;
      min-width: 5.5rem;
      text-align: center;
      font-weight: 700;
    }

    .stack {
      display: grid;
      gap: 1rem;
    }
    .deal-card {
      background: rgba(255,255,255,0.8);
      box-shadow: var(--shadow);
    }
    .deal-card.highlight {
      background: linear-gradient(180deg, rgba(245, 215, 198, 0.7), rgba(255,255,255,0.9));
    }
    .deal-row {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      align-items: end;
    }
    .deal-tag {
      display: inline-flex;
      align-items: center;
      gap: 0.4rem;
      font-size: 0.8rem;
      color: var(--accent-strong);
      background: rgba(173,92,47,0.12);
      padding: 0.45rem 0.7rem;
      border-radius: 999px;
      font-weight: 700;
    }

    .editorial-grid {
      grid-template-columns: repeat(3, 1fr);
    }
    .editorial-card {
      background: rgba(255,255,255,0.82);
      display: grid;
      gap: 1rem;
    }
    .editorial-art {
      min-height: 170px;
      border-radius: 20px;
      background:
        linear-gradient(135deg, rgba(173,92,47,0.24), rgba(173,92,47,0.04)),
        linear-gradient(135deg, #f1ece5, #ffffff);
      position: relative;
      overflow: hidden;
    }
    .editorial-art::after {
      content: "";
      position: absolute;
      inset: auto -1rem -2rem auto;
      width: 8rem;
      height: 8rem;
      border-radius: 30% 70% 55% 45% / 44% 37% 63% 56%;
      background: rgba(173,92,47,0.18);
    }

    .promo-card {
      display: grid;
      grid-template-columns: 1.1fr 0.9fr;
      gap: 1rem;
      align-items: center;
      background: linear-gradient(135deg, rgba(255,255,255,0.85), rgba(245,242,236,0.8));
    }
    form {
      display: flex;
      gap: 0.6rem;
      flex-wrap: wrap;
    }
    input[type="email"] {
      flex: 1 1 16rem;
      border: 1px solid var(--border);
      border-radius: 999px;
      padding: 0.95rem 1rem;
      background: rgba(255,255,255,0.92);
    }

    .footer {
      padding: 2rem 0 3rem;
      color: var(--muted);
      text-align: center;
    }

    @media (max-width: 960px) {
      nav { display: none; }
      .hero-grid, .deal-layout, .promo-card, .editorial-grid, .featured-grid { grid-template-columns: 1fr; }
      .featured-grid .card:nth-child(n) { grid-column: auto; }
      .hero-main { min-height: auto; }
    }

    @media (max-width: 640px) {
      .shell { width: min(var(--max), calc(100% - 1.25rem)); }
      .topbar { padding: 0.8rem 0; }
      .actions .ghost-btn { display: none; }
      .hero-main, .hero-side, .deal-banner, .deal-card, .editorial-card, .promo-card { padding: 1rem; }
      h1 { max-width: 100%; }
      .hero-art { grid-template-columns: 1fr; }
      .product-meta, .deal-row, .section-head { align-items: start; flex-direction: column; }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to content</a>

  <header>
    <div class="shell topbar">
