          <div class="hero-art" aria-label="Store highlights">
            <div class="stat-strip">
              <div class="stat">
                <strong>240+</strong>
                <span class="muted">Curated products</span>
              </div>
              <div class="stat">
                <strong>48 hrs</strong>
                <span class="muted">Fast shipping window</span>
              </div>
