        <aside class="hero-side">
          <div class="feature-visual">
            <span class="eyebrow" style="color: rgba(255,255,255,0.85)">Featured drop</span>
            <div>
              <h2 style="margin:0 0 0.35rem; font-size: 2rem;">The Lounge Edit</h2>
              <p style="margin:0; max-width: 20ch; color: rgba(255,255,255,0.82);">Soft textures, warm tones, and sculptural silhouettes.</p>
