  <script>
    const featuredProducts = [
      {
        name: "Alder Lounge Chair",
        category: "Furniture",
        price: "$289",
        rating: "★★★★☆ 4.9",
        description: "A low-profile accent chair with a rounded frame and textured fabric.",
        visualClass: "one"
      },
      {
        name: "Mara Table Lamp",
        category: "Lighting",
        price: "$96",
        rating: "★★★★★ 5.0",
        description: "Warm ambient light with a ceramic base and linen shade.",
        visualClass: "two"
      },
      {
        name: "Terra Accent Vessel",
        category: "Decor",
        price: "$42",
        rating: "★★★★☆ 4.8",
        description: "Hand-finished decor piece that layers well on shelves and consoles.",
        visualClass: "three"
      }
    ];

    const editorialStories = [
      {
        title: "How to build a calm, layered living room",
        text: "A practical guide to balancing statement pieces, soft textures, and flexible seating."
      },
      {
        title: "The 5-minute entryway reset",
        text: "Small storage swaps and styling cues that make first impressions feel effortless."
      },
      {
        title: "Seasonal color story: sand, moss, and clay",
        text: "See how warm neutrals create depth without overwhelming a space."
      }
    ];

    const featuredGrid = document.getElementById("featured-grid");
    const editorialGrid = document.getElementById("editorial-grid");

    featuredGrid.innerHTML = featuredProducts.map((product) => `
      <article class="card">
        <div class="product-visual ${product.visualClass}" aria-hidden="true"></div>
        <div class="product-meta">
          <div>
            <div class="eyebrow">${product.category}</div>
            <h3>${product.name}</h3>
            <p class="muted">${product.description}</p>
          </div>
          <div class="price">${product.price}</div>
        </div>
        <div class="product-meta">
          <div class="rating" aria-label="Rated ${product.rating.replace('★★★★☆ ', '').replace('★★★★★ ', '')} out of 5">${product.rating}</div>
          <button class="ghost-btn" type="button" style="padding-inline:1rem;">Add to cart</button>
        </div>
      </article>
    `).join("");

    editorialGrid.innerHTML = editorialStories.map((story) => `
      <article class="editorial-card">
        <div class="editorial-art" aria-hidden="true"></div>
        <div>
          <div class="eyebrow">Read more</div>
          <h3>${story.title}</h3>
          <p class="muted">${story.text}</p>
          <button class="ghost-btn" type="button" style="padding-inline:1rem;">Explore story</button>
        </div>
      </article>
