  <title>Northstar Home | Modern Retail</title>
  <meta name="description" content="A clean, modern ecommerce home page for a retail brand featuring products, deals, and editorial content.">
  <style>
    :root {
      color-scheme: light;
      --bg: #f5f2ec;
      --surface: #ffffff;
      --surface-alt: #f0ebe4;
      --text: #1c1a17;
      --muted: #6c655c;
      --border: rgba(28, 26, 23, 0.1);
      --accent: #ad5c2f;
      --accent-strong: #8f4420;
      --accent-soft: #f5d7c6;
      --shadow: 0 20px 50px rgba(28, 26, 23, 0.08);
      --radius-xl: 28px;
      --radius-lg: 20px;
      --radius-md: 14px;
      --max: 1180px;
    }

    * { box-sizing: border-box; }
    html { scroll-behavior: smooth; }
    body {
      margin: 0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top left, rgba(173, 92, 47, 0.14), transparent 28%),
        radial-gradient(circle at right 12%, rgba(76, 105, 90, 0.1), transparent 22%),
        var(--bg);
      color: var(--text);
      line-height: 1.5;
    }

    img { max-width: 100%; display: block; }
    a { color: inherit; text-decoration: none; }
    button, input { font: inherit; }
    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }
    :focus-visible {
      outline: 3px solid var(--accent);
      outline-offset: 3px;
    }

    .skip-link {
      position: absolute;
      left: -999px;
