      padding: 0.75rem 1rem;
      border-radius: 999px;
      z-index: 1000;
    }
    .skip-link:focus { left: 1rem; }

    .shell {
      width: min(var(--max), calc(100% - 2rem));
      margin: 0 auto;
    }

    header {
      position: sticky;
      top: 0;
      z-index: 50;
