    }

    .topbar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding: 1rem 0;
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 0.75rem;
      font-weight: 800;
      letter-spacing: 0.02em;
    }
    .brand-mark {
      width: 2.3rem;
      height: 2.3rem;
      border-radius: 0.8rem;
      display: grid;
      place-items: center;
      background: linear-gradient(135deg, var(--accent), #d07a3a);
      color: white;
      box-shadow: 0 10px 30px rgba(173, 92, 47, 0.25);
    }

    nav ul {
      list-style: none;
      display: flex;
      gap: 1.2rem;
      padding: 0;
      margin: 0;
      color: var(--muted);
      flex-wrap: wrap;
    }
    nav a:hover { color: var(--text); }

    .actions {
      display: flex;
      gap: 0.75rem;
      align-items: center;
    }
    .icon-btn, .primary-btn, .ghost-btn, .chip {
      border: 0;
      border-radius: 999px;
      transition: transform 160ms ease, background 160ms ease, color 160ms ease, box-shadow 160ms ease;
    }
    .icon-btn {
      width: 2.75rem;
      height: 2.75rem;
      display: grid;
      place-items: center;
      background: rgba(255,255,255,0.8);
      box-shadow: inset 0 0 0 1px var(--border);
      cursor: pointer;
    }
    .icon-btn:hover, .primary-btn:hover, .ghost-btn:hover, .chip:hover { transform: translateY(-1px); }

    .hero {
      padding: 2rem 0 1rem;
    }
    .hero-grid {
      display: grid;
      grid-template-columns: 1.15fr 0.85fr;
      gap: 1.25rem;
      align-items: stretch;
    }

    .hero-main, .hero-side, .card, .panel, .editorial-card, .promo-card {
      background: rgba(255,255,255,0.75);
      border: 1px solid rgba(28,26,23,0.08);
      box-shadow: var(--shadow);
      backdrop-filter: blur(12px);
    }
    .hero-main {
      border-radius: var(--radius-xl);
      padding: 2rem;
      min-height: 500px;
      display: grid;
      grid-template-columns: 1fr;
      gap: 1.5rem;
      position: relative;
      overflow: hidden;
    }
    .hero-main::after {
      content: "";
      position: absolute;
      inset: auto -6rem -7rem auto;
