    .hero-copy {
      max-width: 36rem;
      color: var(--muted);
      font-size: 1.06rem;
    }
    .hero-cta {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
      margin-top: 1.5rem;
    }
    .primary-btn, .ghost-btn {
      padding: 0.95rem 1.25rem;
      font-weight: 700;
      cursor: pointer;
    }
    .primary-btn {
      background: var(--text);
      color: #fff;
      box-shadow: 0 16px 30px rgba(28, 26, 23, 0.16);
    }
    .ghost-btn {
      background: rgba(255,255,255,0.8);
      color: var(--text);
      box-shadow: inset 0 0 0 1px var(--border);
    }

    .hero-art {
      margin-top: auto;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 1rem;
