      background: rgba(173,92,47,0.18);
    }

    .promo-card {
      display: grid;
      grid-template-columns: 1.1fr 0.9fr;
      gap: 1rem;
      align-items: center;
      background: linear-gradient(135deg, rgba(255,255,255,0.85), rgba(245,242,236,0.8));
    }
    form {
      display: flex;
      gap: 0.6rem;
      flex-wrap: wrap;
    }
    input[type="email"] {
      flex: 1 1 16rem;
      border: 1px solid var(--border);
